const familyLabels: Record<HoldType["family"], string> = {
  foundational: "אחיזות יסוד",
  directional: "אחיזות כיווניות",
  "structural-special": "אחיזות גדולות, מבניות ומיוחדות",
  "feet-only": "אחיזות רגליים בלבד",
  "outdoor-rock": "אחיזות אופייניות לטיפוס בטבע",
};

async function writeHoldTypes() {
  const dir = path.join(ROOT, "src/content/hold-types");
  await mkdir(dir, { recursive: true });

  for (const hold of holdTypes) {
    const frontmatter = [
      "---",
      `nameHe: "${hold.nameHe.replace(/"/g, '\\"')}"`,
      `nameEn: "${hold.nameEn.replace(/"/g, '\\"')}"`,
      `family: ${hold.family}`,
      `order: ${hold.order}`,
      `iconId: ${hold.iconId}`,
      `summary: "${hold.summary.replace(/"/g, '\\"')}"`,
      ...(hold.relatedHoldSlugs
        ? [
            "relatedHoldSlugs:",
            ...hold.relatedHoldSlugs.map((s) => `  - ${s}`),
          ]
        : []),
      "---",
      "",
      hold.body.trim(),
      "",
    ].join("\n");

    await writeFile(path.join(dir, `${hold.slug}.md`), frontmatter, "utf-8");
  }

  console.log(`hold-types: wrote ${holdTypes.length} files -> ${dir}`);
  for (const [key, label] of Object.entries(familyLabels)) {
    const count = holdTypes.filter((h) => h.family === key).length;
    console.log(`  ${label}: ${count}`);
  }
}

async function writeMdFile(
  dir: string,
  slug: string,
  frontmatterLines: string[],
  body: string,
) {
  const content = ["---", ...frontmatterLines, "---", "", body.trim(), ""].join(
    "\n",
  );
  await writeFile(path.join(dir, `${slug}.md`), content, "utf-8");
}

function yamlStr(value: string) {
  return `"${value.replace(/"/g, '\\"')}"`;
}

