const glossaryCategoryLabels: Record<GlossaryTerm["category"], string> = {
  "movement-technique": "תנועה וטכניקה על הקיר",
  "sending-attempts": "הצלחה, ניסיונות ומהלך הטיפוס",
  "discipline-style": "סגנונות טיפוס",
  "wall-safety": "מושגי מבנה קיר ובטיחות",
};

async function writeGlossary() {
  const dir = path.join(ROOT, "src/content/glossary");
  await mkdir(dir, { recursive: true });

  for (const term of glossaryTerms) {
    const lines = [
      `termHe: ${yamlStr(term.termHe)}`,
      `termEn: ${yamlStr(term.termEn)}`,
      `category: ${term.category}`,
      `order: ${term.order}`,
      `summary: ${yamlStr(term.summary)}`,
      ...(term.relatedDisciplineSlug
        ? [`relatedDisciplineSlug: ${term.relatedDisciplineSlug}`]
        : []),
    ];
    await writeMdFile(dir, term.slug, lines, term.body ?? term.summary);
  }

  console.log(`glossary: wrote ${glossaryTerms.length} files -> ${dir}`);
  for (const [key, label] of Object.entries(glossaryCategoryLabels)) {
    const count = glossaryTerms.filter((t) => t.category === key).length;
    console.log(`  ${label}: ${count}`);
  }
}

