async function writeDisciplines() {
  const dir = path.join(ROOT, "src/content/disciplines");
  await mkdir(dir, { recursive: true });

  for (const d of disciplines) {
    const lines = [
      `nameHe: ${yamlStr(d.nameHe)}`,
      `nameEn: ${yamlStr(d.nameEn)}`,
      `order: ${d.order}`,
      `environment: ${d.environment}`,
      `summary: ${yamlStr(d.summary)}`,
    ];
    await writeMdFile(dir, d.slug, lines, d.body);
  }

  console.log(`disciplines: wrote ${disciplines.length} files -> ${dir}`);
}

