const techniqueCategoryLabels: Record<Technique["category"], string> = {
  fundamentals: "יסודות התנועה",
  "advanced-movement": "טכניקות תנועה מתקדמות",
  "effort-safety": "ניהול מאמץ ובטיחות",
};

async function writeTechniques() {
  const dir = path.join(ROOT, "src/content/techniques");
  await mkdir(dir, { recursive: true });

  for (const t of techniques) {
    const lines = [
      `nameHe: ${yamlStr(t.nameHe)}`,
      `nameEn: ${yamlStr(t.nameEn)}`,
      `category: ${t.category}`,
      `order: ${t.order}`,
      `summary: ${yamlStr(t.summary)}`,
    ];
    await writeMdFile(dir, t.slug, lines, t.body);
  }

  console.log(`techniques: wrote ${techniques.length} files -> ${dir}`);
  for (const [key, label] of Object.entries(techniqueCategoryLabels)) {
    const count = techniques.filter((t) => t.category === key).length;
    console.log(`  ${label}: ${count}`);
  }
}

