type ClimbingStyle =
  | "bouldering"
  | "lead"
  | "top-rope"
  | "speed"
  | "trad"
  | "multi-pitch"
  | "via-ferrata";

type Region = "north" | "sharon" | "center" | "shfela" | "jerusalem" | "yosh" | "south";

interface GymLocation {
  slug: string;
  kind: "gym";
  name: string;
  chain?: string;
  city: string;
  region: Region;
  address?: string;
  phone?: string;
  website?: string;
  styles: ClimbingStyle[];
  description?: string;
  coordinates?: { lat: number; lng: number };
}

interface CragLocation {
  slug: string;
  kind: "crag";
  name: string;
  region: Region;
  styles: ClimbingStyle[];
  description?: string;
  coordinates?: { lat: number; lng: number };
  locationDescription?: string;
  rockType?: string;
  routeLength?: string;
  routeCount?: string;
  season?: string;
  shade?: string;
  lodging?: string;
  guidebooks?: { label: string; url: string }[];
  externalBetaUrl?: string;
  climbingProhibited?: boolean;
  // Overrides CROWD_SOURCE_NOTE below - only for crags whose data didn't
  // come from the usual ILCA/community-update pipeline (e.g. a guided
  // commercial activity sourced straight from the operator's own site).
  sourceNote?: string;
}

type LocationItem = GymLocation | CragLocation;

