const regionLabels: Record<Region, string> = {
  north: "צפון",
  sharon: "שרון",
  center: "מרכז",
  shfela: "שפלה",
  jerusalem: "אזור ירושלים",
  yosh: "יהודה ושומרון",
  south: "דרום",
};

async function writeLocations() {
  const dir = path.join(ROOT, "src/content/locations");
  await mkdir(dir, { recursive: true });

  const all: LocationItem[] = [...gyms, ...crags];

  for (const loc of all) {
    const g = loc.kind === "gym" ? (loc as GymLocation) : null;
    const c = loc.kind === "crag" ? (loc as CragLocation) : null;
    const lines = [
      `kind: ${loc.kind}`,
      `name: ${yamlStr(loc.name)}`,
      "styles:",
      ...loc.styles.map((s) => `  - ${s}`),
      `region: ${loc.region}`,
      ...(g ? [`city: ${yamlStr(g.city)}`] : []),
      ...(g?.chain ? [`chain: ${yamlStr(g.chain)}`] : []),
      ...(g?.address ? [`address: ${yamlStr(g.address)}`] : []),
      ...(g?.phone ? [`phone: ${yamlStr(g.phone)}`] : []),
      ...(g?.website ? [`website: ${yamlStr(g.website)}`] : []),
      ...(loc.description ? [`description: ${yamlStr(loc.description)}`] : []),
      ...(loc.coordinates
        ? ["coordinates:", `  lat: ${loc.coordinates.lat}`, `  lng: ${loc.coordinates.lng}`]
        : []),
      ...(c?.locationDescription ? [`locationDescription: ${yamlStr(c.locationDescription)}`] : []),
      ...(c?.rockType ? [`rockType: ${yamlStr(c.rockType)}`] : []),
      ...(c?.routeLength ? [`routeLength: ${yamlStr(c.routeLength)}`] : []),
      ...(c?.routeCount ? [`routeCount: ${yamlStr(c.routeCount)}`] : []),
      ...(c?.season ? [`season: ${yamlStr(c.season)}`] : []),
      ...(c?.shade ? [`shade: ${yamlStr(c.shade)}`] : []),
      ...(c?.lodging ? [`lodging: ${yamlStr(c.lodging)}`] : []),
      ...(c?.guidebooks && c.guidebooks.length > 0
        ? [
            "guidebooks:",
            ...c.guidebooks.flatMap((g) => [
              `  - label: ${yamlStr(g.label)}`,
              `    url: ${yamlStr(g.url)}`,
            ]),
          ]
        : []),
      ...(c?.externalBetaUrl ? [`externalBetaUrl: ${yamlStr(c.externalBetaUrl)}`] : []),
      ...(c?.climbingProhibited ? [`climbingProhibited: true`] : []),
      `sourceNote: ${yamlStr(loc.kind === "gym" ? GYM_SOURCE_NOTE : (c?.sourceNote ?? CROWD_SOURCE_NOTE))}`,
    ];
    const body =
      loc.description ??
      (loc.kind === "gym"
        ? `${loc.name} - קיר טיפוס ב${g!.city}.`
        : `אתר טיפוס בטבע באזור ${regionLabels[loc.region]}.`);
    await writeMdFile(dir, loc.slug, lines, body);
  }

  console.log(`locations: wrote ${all.length} files -> ${dir}`);
  console.log(`  gyms: ${gyms.length}, crags: ${crags.length}`);
}

await writeHoldTypes();
await writeGlossary();
await writeDisciplines();
await writeTechniques();
await writeInjuryPrevention();
await writeGear();
await writeLocations();
